@regehr, confirm I reproduced it with your snippet – now I wonder how I did get the IR I pasted above. Can you reproduce the issue when invoking latest clang with IR out of curiosity? I get the following:

```
% cat foo.ll 
declare i64 @llvm.sshl.sat.i64(i64, i64) #0

define i64 @f(i64 %0, i64 %1, i64 %2) {
  %4 = or i64 %0, 1
  %5 = add i64 %4, %0
  %6 = sub nsw i64 %1, %5
  %7 = call i64 @llvm.sshl.sat.i64(i64 %6, i64 1)
  ret i64 %7
}
% cat driver.c 
#include <stdio.h>

// i64 %#0 = #x5dbdff5f99a88000 (6754835802190544896)
// i64 %#1 = #x0000000000000000 (0)
// i64 %#2 = #x0000000000000000 (0)

unsigned long f(unsigned long, unsigned long, unsigned long);

int main(void) {
  printf("%lx\n", f(6754835802190544896ULL, 0, 0));
}
% ./build/bin/clang driver.c foo.ll && ./a.out
7fffffffffffffff
```

> From what I can tell there is a combine in the machinecombiner that is reassociating add/sub. It should be dropping the nsw flags but doesn't, which allows AArch64InstrInfo::substituteCmpToZero to remove the condition even with them using the V condition flag.

Looks correct considering the reassociation being done, I confirm this stops the miscompilation:

```diff
--- a/llvm/lib/Target/AArch64/AArch64InstrInfo.cpp
+++ b/llvm/lib/Target/AArch64/AArch64InstrInfo.cpp
@@ -6918,14 +6918,22 @@ genSubAdd2SubSub(MachineFunction &MF, MachineRegisterInfo &MRI,
     assert((Opcode == AArch64::SUBWrr || Opcode == AArch64::SUBXrr) &&
            "Unexpected instruction opcode.");
 
+  uint32_t RootFlags = Root.getFlags();
+  if (RootFlags & MachineInstr::NoSWrap)
+    Root.clearFlag(MachineInstr::NoSWrap);
+  if (RootFlags & MachineInstr::NoUWrap)
+    Root.clearFlag(MachineInstr::NoUWrap);
+
   MachineInstrBuilder MIB1 =
       BuildMI(MF, MIMetadata(Root), TII->get(Opcode), NewVR)
           .addReg(RegA, getKillRegState(RegAIsKill))
-          .addReg(RegB, getKillRegState(RegBIsKill));
+          .addReg(RegB, getKillRegState(RegBIsKill))
+          .setMIFlags(Root.getFlags());
   MachineInstrBuilder MIB2 =
       BuildMI(MF, MIMetadata(Root), TII->get(Opcode), ResultReg)
           .addReg(NewVR, getKillRegState(true))
-          .addReg(RegC, getKillRegState(RegCIsKill));
+          .addReg(RegC, getKillRegState(RegCIsKill))
+          .setMIFlags(Root.getFlags());
 
   InstrIdxForVirtReg.insert(std::make_pair(NewVR, 0));
```

cc/ @davemgreen

patch:
commit 23b6709c72357c8b8f0ffa6cdbd860977441982b
Author: Antonio Frighetto <me@antoniofrighetto.com>
Date:   Thu Apr 25 09:49:24 2024 +0200

    [AArch64] Drop poison-generating flags in `genSubAdd2SubSub` combiner

    A miscompilation issue has been addressed with improved handling.

    Fixes: https://github.com/llvm/llvm-project/issues/88950.

diff --git a/llvm/lib/Target/AArch64/AArch64InstrInfo.cpp b/llvm/lib/Target/AArch64/AArch64InstrInfo.cpp
index 7bf06e71a030..55fecc4b4845 100644
--- a/llvm/lib/Target/AArch64/AArch64InstrInfo.cpp
+++ b/llvm/lib/Target/AArch64/AArch64InstrInfo.cpp
@@ -6924,19 +6924,26 @@ genSubAdd2SubSub(MachineFunction &MF, MachineRegisterInfo &MRI,
     assert((Opcode == AArch64::SUBWrr || Opcode == AArch64::SUBXrr) &&
            "Unexpected instruction opcode.");

+  uint32_t Flags = Root.mergeFlagsWith(*AddMI);
+  Flags &= ~MachineInstr::NoSWrap;
+  Flags &= ~MachineInstr::NoUWrap;
+
   MachineInstrBuilder MIB1 =
       BuildMI(MF, MIMetadata(Root), TII->get(Opcode), NewVR)
           .addReg(RegA, getKillRegState(RegAIsKill))
-          .addReg(RegB, getKillRegState(RegBIsKill));
+          .addReg(RegB, getKillRegState(RegBIsKill))
+          .setMIFlags(Flags);
   MachineInstrBuilder MIB2 =
       BuildMI(MF, MIMetadata(Root), TII->get(Opcode), ResultReg)
           .addReg(NewVR, getKillRegState(true))
-          .addReg(RegC, getKillRegState(RegCIsKill));
+          .addReg(RegC, getKillRegState(RegCIsKill))
+          .setMIFlags(Flags);

   InstrIdxForVirtReg.insert(std::make_pair(NewVR, 0));
   InsInstrs.push_back(MIB1);
   InsInstrs.push_back(MIB2);
   DelInstrs.push_back(AddMI);
+  DelInstrs.push_back(&Root);
 }

 /// When getMachineCombinerPatterns() finds potential patterns,
@@ -6966,13 +6973,13 @@ void AArch64InstrInfo::genAlternativeCodeSequence(
     // ==> (A - B) - C
     genSubAdd2SubSub(MF, MRI, TII, Root, InsInstrs, DelInstrs, 1,
                      InstrIdxForVirtReg);
-    break;
+    return;
   case AArch64MachineCombinerPattern::SUBADD_OP2:
     // A - (B + C)
     // ==> (A - C) - B
     genSubAdd2SubSub(MF, MRI, TII, Root, InsInstrs, DelInstrs, 2,
                      InstrIdxForVirtReg);
-    break;
+    return;
   case AArch64MachineCombinerPattern::MULADDW_OP1:
   case AArch64MachineCombinerPattern::MULADDX_OP1:
     // MUL I=A,B,0

